/**
 * Test flow for createTask action
 * Demonstrates creating a task
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testCreateTask = Flow(
    {
        $id: Now.ID['test_create_task_flow'],
        name: 'Test Create Task',
        description: 'Tests the createTask core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_create_task_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.createTask,
            { $id: Now.ID['test_create_task_action'] },
            {
                task_table: 'task',
                field_values: TemplateValue({
                    short_description: 'Test Task',
                    priority: 3,
                    parent: `${wfa.dataPill(_params.trigger.current.sys_id, 'string')}`,
                }),
                wait: false,
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_create_task_log'] },
            {
                log_level: 'info',
                log_message: `createTask outputs: Record=${wfa.dataPill(result.Record, 'string')}, Table=${wfa.dataPill(result.Table, 'string')}`,
            }
        )
    }
)
